const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['辦活動想向民眾募款要不要許可','第7條'],['募款一定要報備嗎','許可'],['勸募要先申請許可嗎','21日前'],
['街頭發傳單收小額捐款可以嗎','沒有訂'],['擺攤向路人募款可以嗎','不特定'],
['勸募許可忘記申請會怎樣','4萬'],['沒申請就募款會被罰嗎','返還'],
['收會員的捐款算勸募嗎','第33條'],['只跟會員募款需要申請嗎','五個月'],
['募款跟捐款有什麼差別','主動'],['勸募條例是啥','第24條'],
['勸募錢花不完怎麼辦','三個月'],['勸募收到的錢可以拿來付薪水嗎','必要支出'],
['補助款可以拿來發獎金嗎','獎金'],['補助款可以轉給別的團體嗎','追繳'],
['沒收據可以核銷嗎','單據'],['補助核銷來不及怎麼辦','20日'],['補助款核銷逾期會怎樣','註銷'],
['補助成果報告要寫什麼','照片'],['補助款要放在協會帳戶嗎','第16條'],['補助款的利息要怎麼處理','第20條'],
['拿到補助要不要先開會討論','第6點'],['協會欠繳會費可以申請補助嗎','五種'],['補助款可以買什麼','研習']];
const no=['合作社可以募款嗎','魅力社區補助款可以發獎金嗎','勸募要先向誰申請','勸募活動辦完要公開什麼','補助款核銷要準備什麼','補助款用不完要退嗎','基金會可以募款嗎','政黨可以募款嗎','寺廟募款要申請嗎','捐款可以抵稅嗎','補助款可以買電腦嗎','補助款可以付薪水嗎','工會會費欠繳怎麼辦','志工的補助怎麼領','補助申請被駁回怎麼辦'];
const mine=/^(向會員募款|公益勸募條例在規定|沒有申請勸募許可|募款（勸募）和捐款|勸募的錢沒花完|勸募所得可以付人事費|向民眾募款|募款要不要先申請|補助款可以發獎金|補助款可以轉給|沒有收據發票|補助核銷來不及|補助的成果報告|補助款要放在協會|補助款存款的利息|申請補助要不要先經|欠繳會費可以申請|補助款可以用在哪些)/;
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const x=a&&a.title?(a.title+a.summary):'';if(!x.includes(e)||!a.direct||!mine.test(a.title)){bad++;console.log('✗',q,a&&a.title)}});
no.forEach(q=>{const a=A(q);if(a&&a.title&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
